<template><nav class="navbar"><RouterLink v-for="item in navItems" :key="item.path" :to="item.path" class="navbar-item" :class="{ active: isActive(item.path) }"><span class="navbar-label">{{ item.label || t(item.key) }}</span><span v-if="item.key==='navMy'&&unreadCount" class="nav-unread-badge">{{ unreadCount>99?'99+':unreadCount }}</span><span v-if="item.key==='navChat'&&unreadMessagesCount" class="nav-unread-badge">{{ unreadMessagesCount>99?'99+':unreadMessagesCount }}</span></RouterLink></nav></template>
<script setup>import { computed, onMounted, onUnmounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { useAuth,useLang } from '../contexts/app'; import { messageService } from '../services/messageService'; import { postService } from '../services/postService'; import { getMutedGroupIds } from '../utils/groupMute'; import './NavBar.css'; const route=useRoute(); const {isLoggedIn,user}=useAuth(); const {t}=useLang(); const unreadCount=ref(0),unreadMessagesCount=ref(0); const navItems=computed(()=>{const a=[{key:'navLatest',path:'/'},{key:'navFeatured',path:'/featured'},{key:'navLive',path:'/live'},{key:'navOC',path:'/oc'},{key:'navMy',path:'/my'},{key:'navChat',path:'/messages'}];if(user.value?.is_admin)a.push({key:'navAdmin',path:'/admin',label:'管理'});return a}); const isActive=path=>path==='/'?route.path==='/':route.path===path||route.path.startsWith(`${path}/`); let timer; const fetchUnread=async()=>{if(!isLoggedIn.value){unreadCount.value=unreadMessagesCount.value=0;return}try{const [n,c,g,i]=await Promise.all([postService.getUnreadNotificationsCount(),messageService.getConversations(),messageService.getGroups(),messageService.getGroupInvites()]);const muted=new Set(getMutedGroupIds());unreadCount.value=(n.unread_count||0)+i.length;unreadMessagesCount.value=c.reduce((s,x)=>s+(x.unread_count||0),0)+g.reduce((s,x)=>s+(muted.has(x.id)?0:x.unread_count||0),0)+i.length}catch{}}; const handleNotif=e=>{if(e.detail?.action==='readAll')unreadCount.value=0;else if(e.detail?.action==='readOne')unreadCount.value=Math.max(0,unreadCount.value-1);fetchUnread()}; const refresh=()=>{if(document.visibilityState==='visible')fetchUnread()}; onMounted(()=>{fetchUnread();timer=setInterval(fetchUnread,3000);window.addEventListener('messageDataChanged',fetchUnread);window.addEventListener('messageUnreadStateChanged',fetchUnread);window.addEventListener('groupMuteChanged',fetchUnread);window.addEventListener('notificationRead',handleNotif);window.addEventListener('focus',refresh);document.addEventListener('visibilitychange',refresh)});onUnmounted(()=>{clearInterval(timer);window.removeEventListener('messageDataChanged',fetchUnread);window.removeEventListener('messageUnreadStateChanged',fetchUnread);window.removeEventListener('groupMuteChanged',fetchUnread);window.removeEventListener('notificationRead',handleNotif);window.removeEventListener('focus',refresh);document.removeEventListener('visibilitychange',refresh)});</script>
